@Component("dividend-entity-projector")
public class DividendEntityProjector implements EntityProjector<Dividend>{
		
	// core constructor
	public DividendEntityProjector(ProjectorRegistry registry,
										DividendRepository repository ) {
        this.registry 	= registry;
		this.repository = repository;
    }

	@Override
	public Class<Dividend> getEntityClass() {
		return Dividend.class;
	}

    /*
	 * Insert a Dividend
	 * 
     * @param	entity Dividend
     */
    public Dividend create( Dividend entity) {
	    LOGGER.info("creating " + entity.toString() );
	   
    	// ------------------------------------------
    	// persist a new one
    	// ------------------------------------------ 
	    return repository.save(entity);
        
    }

	/*
	 * Update a Dividend
	 * 
     * @param	entity Dividend
     */
    public Dividend update( Dividend entity) {
	    LOGGER.info("updating " + entity.toString() );

	    // ------------------------------------------
    	// save with an existing instance
    	// ------------------------------------------ 
		return repository.save(entity);

    }
    
	/*
	 * Delete a Dividend
	 * 
     * @param	id		UUID
     */
    public Dividend delete( UUID id ) {
	    LOGGER.info("deleting " + id.toString() );

    	// ------------------------------------------
    	// locate the entity by the provided id
    	// ------------------------------------------
	    Dividend entity = repository.findById(id).get();
	    
    	// ------------------------------------------
    	// delete what is discovered 
    	// ------------------------------------------
    	repository.delete( entity );
    	
    	return entity;
    }    

    /*
     * Assign a CorporateAction
     * 
     * @param	parentId	UUID
     * @param	assignment 	CorporateAction 
     * @return	Dividend
     */
    public Dividend assignCorporateAction( UUID parentId, CorporateAction assignment ) {
	    LOGGER.info("assigning CorporateAction as " + assignment.toString() );

	    Dividend parentEntity = repository.findById( parentId ).get();
	    assignment = registry.project( CorporateAction.class, assignment.getCorporateActionId());

	    // ------------------------------------------
		// assign the CorporateAction to the parent entity
		// ------------------------------------------ 
	    parentEntity.setCorporateAction( assignment );

	    // ------------------------------------------
    	// save the parent entity
    	// ------------------------------------------ 
	    repository.save(parentEntity);
        
	    return parentEntity;
    }
    

	/*
	 * Unassign the CorporateAction
	 * 
	 * @param	parentId		UUID
	 * @return	Dividend
	 */
	public Dividend unAssignCorporateAction( UUID parentId ) {
		Dividend parentEntity = repository.findById(parentId).get();

		LOGGER.info("unAssigning CorporateAction on " + parentEntity.toString() );
		
	    // ------------------------------------------
		// null out the CorporateAction on the parent entithy
		// ------------------------------------------     
	    parentEntity.setCorporateAction(null);

	    // ------------------------------------------
		// save the parent entity
		// ------------------------------------------ 
	    repository.save(parentEntity);
    
	    return parentEntity;
	}




    /**
     * Method to retrieve the Dividend via an FindDividendQuery
     * @return 	query	FindDividendQuery
     */
    @SuppressWarnings("unused")
    public Dividend find( UUID id ) {
    	LOGGER.info("handling find using " + id.toString() );
    	try {
    		return repository.findById(id).get();
    	}
    	catch( IllegalArgumentException exc ) {
    		LOGGER.warn( "Failed to find a Dividend - {0}", exc.getMessage() );
    	}
    	return null;
    }
    
    /**
     * Method to retrieve a collection of all Dividends
     *
     * @param	query	FindAllDividendQuery 
     * @return 	List<Dividend> 
     */
    @SuppressWarnings("unused")
    public List<Dividend> findAll( FindAllDividendQuery query ) {
    	LOGGER.info("handling findAll using " + query.toString() );
    	try {
    		return repository.findAll();
    	}
    	catch( IllegalArgumentException exc ) {
    		LOGGER.warn( "Failed to find all Dividend - {0}", exc.getMessage() );
    	}
    	return null;
    }


    //--------------------------------------------------
    // attributes
    // --------------------------------------------------
	@Autowired
    protected final DividendRepository repository;
	protected final ProjectorRegistry registry;


    private static final Logger LOGGER 	= LoggerFactory.getLogger(DividendEntityProjector.class.getName());

}
